package com.hbm.client.machine.pa.cooled;
import com.hbm.client.gui.LegacyContainerScreen;
import com.hbm.fluid.FluidTank;
import com.hbm.item.fluid.client.FluidInfo;
import com.hbm.machine.pa.cooled.*;
import com.hbm.machine.pa.parts.PaCoilItem;
import com.mojang.blaze3d.vertex.*;
import java.util.*;
import net.minecraft.ChatFormatting;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.client.renderer.RenderType;
import net.minecraft.client.resources.sounds.SimpleSoundInstance;
import net.minecraft.locale.Language;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.world.entity.player.Inventory;
import net.neoforged.neoforge.network.PacketDistributor;
/** Source five176x204 GUIs, exact slot/tank/status/coil and three direction control artwork. */
public final class PaScreen extends LegacyContainerScreen<PaMenu>{
 private EditBox threshold;
 private static final class Lines extends RenderType{private Lines(){super("unused",DefaultVertexFormat.POSITION_COLOR,VertexFormat.Mode.DEBUG_LINES,256,false,false,()->{},()->{});}static final RenderType ARROWS=create("hbm_pa_dipole_directions",DefaultVertexFormat.POSITION_COLOR,VertexFormat.Mode.DEBUG_LINES,256,false,false,CompositeState.builder().setShaderState(POSITION_COLOR_SHADER).setLineState(new LineStateShard(OptionalDouble.of(3))).setCullState(NO_CULL).createCompositeState(false));}
 public PaScreen(PaMenu menu,Inventory inventory,Component title){super(menu,inventory,title,ResourceLocation.parse("hbm:textures/gui/particleaccelerator/gui_"+menu.kind.id.substring(3)+".png"),176,204);}
 private PaCooledEntity machine(){return minecraft!=null&&minecraft.level!=null&&minecraft.level.getBlockEntity(menu.position) instanceof PaCooledEntity be?be:null;}
 @Override protected void init(){super.init();if(menu.kind==PaKind.DIPOLE){threshold=new EditBox(font,leftPos+47,topPos+77,66,8,Component.translatable("gui.hbm.pa.threshold"));threshold.setBordered(false);threshold.setTextColor(0x00ff00);threshold.setTextColorUneditable(0x00ff00);threshold.setMaxLength(9);threshold.setValue(machine() instanceof PaDipoleEntity dipole?Integer.toString(dipole.threshold):"0");threshold.setResponder(text->{String value=text.startsWith("0")?text.substring(1):text;if(value.isEmpty())value="0";if(!value.equals(text)){threshold.setValue(value);return;}if(value.chars().allMatch(Character::isDigit)){try{var tag=new CompoundTag();tag.putInt("threshold",Integer.parseInt(value));send(tag);}catch(NumberFormatException ignored){}}});addRenderableWidget(threshold);}}
 private int powerX(){return menu.kind==PaKind.RFC?53:menu.kind==PaKind.QUADRUPOLE?26:8;}private int tankX(){return menu.kind==PaKind.RFC?89:menu.kind==PaKind.QUADRUPOLE?116:134;}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){var m=machine();if(m==null)return;if(menu.kind!=PaKind.RFC){int center=menu.kind==PaKind.DETECTOR?80:79;g.drawString(font,title,center-font.width(title)/2,menu.kind==PaKind.SOURCE?4:menu.kind==PaKind.DETECTOR?5:6,0xffffff,false);}g.drawString(font,playerInventoryTitle,8,110,4210752,false);g.drawString(font,Component.literal("/123K").withStyle(ChatFormatting.AQUA),tankX()+2,22,4210752,false);int heat=(int)Math.ceil(m.temperature);Component text=Component.literal(heat+"K").withStyle(heat>123?ChatFormatting.RED:ChatFormatting.AQUA);g.drawString(font,text,tankX()+32-font.width(text),12,4210752,false);if(m instanceof PaSourceEntity source){var state=Component.translatable("pa."+source.state.name().toLowerCase(Locale.ROOT));g.drawString(font,state,79-font.width(state)/2,76,source.state.color,false);}}
 @Override protected void renderBg(GuiGraphics g,float partial,int x,int y){super.renderBg(g,partial,x,y);var m=machine();if(m==null)return;int power=(int)(m.getPower()*52/m.getMaxPower());drawLegacyRegion(g,powerX(),70-power,184,52-power,16,power);boolean cool=Math.ceil(m.temperature)<=123;switch(menu.kind){case SOURCE->{if(cool)signal(g,44,16);if(m.getPower()>=PaSourceEntity.USAGE)signal(g,44,41);int color=((PaSourceEntity)m).state.color;g.setColor((color>>16&255)>0?1:0,(color>>8&255)>0?1:0,(color&255)>0?1:0,1);drawLegacyRegion(g,45,73,176,52,68,14);g.setColor(1,1,1,1);}case RFC->{}case QUADRUPOLE,DIPOLE->{boolean dipole=menu.kind==PaKind.DIPOLE;int dx=dipole?18:0,dy=dipole?-10:0;var stack=m.getItem(1);if(cool)signal(g,75+dx,64+dy);if(stack.getItem() instanceof PaCoilItem coil){signal(g,85+dx,64+dy);int ordinal=coil.coil().ordinal();drawLegacyRegion(g,65+dx,30+dy,200+(ordinal%2)*28,(dipole?96:0)+(ordinal/2)*28,28,28);}if(m.getPower()>=100000)signal(g,65+dx,64+dy);if(dipole){var be=(PaDipoleEntity)m;float yaw=minecraft.player==null?0:minecraft.player.getYRot();int[] directions={be.dirLower,be.dirUpper,be.dirRedstone};g.flush();var out=g.bufferSource().getBuffer(Lines.ARROWS);for(int i=0;i<3;i++){line(g,out,68,35+i*14,0xff8080ff,180);line(g,out,68,35+i*14,0xffff0000,yaw-directions[i]*90);}g.flush();}}case DETECTOR->{if(cool)signal(g,43,18);if(m.getPower()>=PaDetectorEntity.USAGE)signal(g,43,43);}}tank(g,m.coolantTanks[0],tankX());tank(g,m.coolantTanks[1],tankX()+18);}
 private void signal(GuiGraphics g,int x,int y){drawLegacyRegion(g,x,y,176,8,8,8);}private void line(GuiGraphics g,VertexConsumer out,int x,int y,int color,float yaw){double angle=Math.toRadians(yaw);var pose=g.pose().last().pose();out.addVertex(pose,leftPos+x,topPos+y,0).setColor(color);out.addVertex(pose,(float)(leftPos+x+6*Math.sin(angle)),(float)(topPos+y+6*Math.cos(angle)),0).setColor(color);}
 private void tank(GuiGraphics g,FluidTank tank,int x){int height=tank.getFill()*52/tank.getMaxFill();if(height<=0)return;int color=tank.getTankType().getTint();g.setColor((color>>16&255)/255F,(color>>8&255)/255F,(color&255)/255F,1);g.blit(tank.getTankType().getTexture(),leftPos+x,topPos+88-height,0,16-height,16,height,16,16);g.setColor(1,1,1,1);}
 @Override public void render(GuiGraphics g,int x,int y,float partial){super.render(g,x,y,partial);var m=machine();if(m==null)return;for(int i=0;i<2;i++)if(legacyInfoHovered(x,y,tankX()+18*i,36,16,52)){var tank=m.coolantTanks[i];var lines=new ArrayList<Component>();lines.add(tank.getTankType().displayName());lines.add(Component.literal(tank.getFill()+"/"+tank.getMaxFill()+"mB"));FluidInfo.append(tank.getTankType(),lines,hasShiftDown());g.renderComponentTooltip(font,lines,x,y);}if(legacyInfoHovered(x,y,powerX(),18,16,52))g.renderTooltip(font,Component.literal(m.getPower()+"/"+m.getMaxPower()+"HE"),x,y);if(m instanceof PaSourceEntity source){if(legacyInfoHovered(x,y,105,16,10,10)){var lines=new ArrayList<Component>();lines.add(Component.translatable("gui.hbm.pa.last_momentum",String.format(Locale.US,"%,d",source.lastSpeed)).withStyle(ChatFormatting.BLUE));for(String text:Language.getInstance().getOrDefault("pa."+source.state.name().toLowerCase(Locale.ROOT)+".desc").split("\\$"))lines.add(Component.literal(text).withStyle(ChatFormatting.YELLOW));g.renderComponentTooltip(font,lines,x,y);}if(legacyInfoHovered(x,y,105,28,10,10))g.renderTooltip(font,Component.translatable("gui.hbm.pa.cancel").withStyle(ChatFormatting.RED),x,y);}if(m instanceof PaDipoleEntity dipole){int[] dir={dipole.dirLower,dipole.dirUpper,dipole.dirRedstone};for(int i=0;i<3;i++)if(legacyInfoHovered(x,y,62,29+14*i,12,12))g.renderComponentTooltip(font,List.of(Component.translatable("gui.hbm.pa.player_orientation").withStyle(ChatFormatting.BLUE),Component.translatable("gui.hbm.pa.output_orientation").withStyle(ChatFormatting.RED),Component.translatable("direction.hbm."+PaDipoleEntity.name(dir[i]))),x,y);}}
 private void send(CompoundTag tag){PacketDistributor.sendToServer(new PaControl(menu.containerId,tag));}
 @Override public boolean mouseClicked(double x,double y,int button){boolean result=super.mouseClicked(x,y,button);if(menu.kind==PaKind.SOURCE&&legacyInfoHovered(x,y,105,28,10,10)){var tag=new CompoundTag();tag.putBoolean("cancel",true);send(tag);click();return true;}if(menu.kind==PaKind.DIPOLE){String[] names={"lower","upper","redstone"};for(int i=0;i<3;i++)if(legacyInfoHovered(x,y,62,29+14*i,12,12)){var tag=new CompoundTag();tag.putBoolean(names[i],true);send(tag);click();return true;}}return result;}private void click(){minecraft.getSoundManager().play(SimpleSoundInstance.forUI(SoundEvents.UI_BUTTON_CLICK,1));}
}
